import{z as n,x as l,o as e,c as d,q as t,j as i,D as o,d as B,s,S as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Booth 乘法","description":"","frontmatter":{"title":"Booth 乘法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/booth-multiplier.md","filePath":"cs/booth-multiplier.md","lastUpdated":1791063341000}'),h={name:"cs/booth-multiplier.md"};function A(p,a,c,m,_,u){const r=l("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="booth-乘法" tabindex="-1">Booth 乘法 <a class="header-anchor" href="#booth-乘法" aria-label="Permalink to &quot;Booth 乘法&quot;">​</a></h1><div class="epigraph"><p>补码乘法不必先取绝对值再贴符号：把乘数里连续的 1 收成一次加与一次减，部分积的条数跟着游程走，而不是跟着每一位走。</p><footer>—— 据 Booth, A Signed Binary Multiplication Technique, QJMA 1951；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/privilege-rings">上一课</a>把组成主干停在可编程、可陷阱、分模式的 RISC-V 核：陷入升特权、<code>mret</code> 降回，用户改不了自己的陷阱入口。本课程接续这条硬件线——ALU、HDL、DRAM、PCIe——不重写 Transformer，也不进限价簿。组成主干的<a href="/cs/array-multiplier">阵列乘法</a>已把无符号部分积铺开，并明确把有符号与 Booth 排除。缺口是：<strong>补码操作数</strong>如何少做几次加，而不是再画一遍与门阵列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>阵列对每一位 \\(a_i\\) 都可能加一次移位后的 \\(b\\)。补码里连续的 \\(1\\) 表示一段已经「快满」的权：例如 \\(0111_2=8-1\\)。Booth 观察：\\(k\\) 个连续 \\(1\\) 等价于在这段的高位加一次、低位减一次。缺口因此不是新的乘法定义，而是把乘数重编码，让部分积从「每比特一条」变成「每游程一对加减」。</p><p>本课只钉基数-2 的 Booth 与其基-4 改良（两位一组看 \\(a_{i+1}a_ia_{i-1}\\)）。华莱士压缩树是下一课的缺口。</p><p><span class="marginnote">数字实例：\\(0111_2\\) 按位算是 \\(4+2+1=7\\)，要加 3 次；重写成 \\(1000-0001=8-1\\)，就只剩一次加一次减。乘数里连续的 1 越长，这一笔账省得越多。</span></p><h3 id="booth-不是「先变正再乘」" tabindex="-1">Booth 不是「先变正再乘」 <a class="header-anchor" href="#booth-不是「先变正再乘」" aria-label="Permalink to &quot;Booth 不是「先变正再乘」&quot;">​</a></h3><p>取绝对值、无符号乘、再按符号位异或贴回，多一次取负，且零与最小负数（\\(-2^{n-1}\\)）要特判。Booth 直接在补码上加减移位后的被乘数，与<a href="/cs/twos-complement">补码</a>同一套加法器。把 Booth 理解成符号处理的软件例程，ALU 里那条独立乘通路会对不齐。</p><p><span class="marginnote">Booth 1951 的原文是机械/台式计算器语境；Harris 把它收成数字电路积木。Patterson/Hennessy 把乘除放到整数乘除单元，不塞进与 <code>add</code> 同深的单周期框。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>考察乘数相邻两位 \\((a_i,a_{i-1})\\)（约定 \\(a_{-1}=0\\)）：\\(00\\) 与 \\(11\\) 什么都不加；\\(01\\) 加被乘数；\\(10\\) 减被乘数。然后算术右移，进入下一位。基-4（modified Booth）：一次看三位，部分积取 \\(\\{0,\\pm B,\\pm 2B\\}\\)，条数大约减半。\\(\\pm 2B\\) 是接线左移，不必另造乘法器。</p>',12)),(e(),i(E,null,{default:o(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MUL%5B%22%E8%A1%A5%E7%A0%81%E4%B9%98%E6%95%B0%22%5D%20--%3E%20ENC%5B%22Booth%20%E9%87%8D%E7%BC%96%E7%A0%81%22%5D%0A%20%20ENC%20--%3E%20PP%5B%22%E6%9B%B4%E5%B0%91%E7%9A%84%E9%83%A8%E5%88%86%E7%A7%AF%22%5D%0A%20%20PP%20--%3E%20ADD%5B%22%E5%8A%A0%E5%87%8F%E4%B8%8E%E7%AE%97%E6%9C%AF%E7%A7%BB%E4%BD%8D%22%5D%0A%20%20ADD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ACSA%20%E5%8E%8B%E7%BC%A9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>阵列仍可生成全部部分积再加；Booth 只改变<strong>有哪些非零部分积</strong>。有符号扩展：被乘数在阵列里要按补码符号扩展到 \\(2n\\) 位宽，否则高位权错。</p><p><span class="marginnote">术语翻译：**游程（run）**就是一串连续相同的位，比如 <code>0111</code> 里的 <code>111</code>。Booth 的全部戏法是：一段 1 的游程 = 段首减 \\(B\\)、段尾后一位加 \\(B\\)（借补码的权），与「这串 1 有几位」无关。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课华莱士树吃的是已经对齐的部分积，不关心它们来自逐位与还是 Booth。RV32M 的 <code>mul</code>/<code>mulh</code> 可以在同一阵列上取低/高 \\(n\\) 位；Booth 编码是微结构选择，不是新 opcode。组成课已强调：组合乘的关键路径长于一次 <a href="/cs/adder-cla">CLA</a>，Booth 减的是加法器个数与部分积高度，末级进位链仍在。</p><p>一段游程如何变成一减一加？看 <code>0010111</code> 的末三位游程 <code>111</code>：</p>',5)),(e(),i(E,null,{default:o(()=>[s(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20RUN%5B%22%E6%B8%B8%E7%A8%8B%20111%EF%BC%88%E6%9D%83%204%2B2%2B1%EF%BC%89%22%5D%20--%3E%20LO%5B%22%E6%AE%B5%E5%B0%BE%E8%A1%A5%E4%B8%80%E4%BD%8D%200%EF%BC%9A01%20%E5%88%A4%E5%AE%9A%E5%87%8F%20B%22%5D%0A%20%20RUN%20--%3E%20HI%5B%22%E6%B8%B8%E7%A8%8B%E4%B8%8A%E6%B2%BF%E8%BF%9B%E4%BD%8D%E6%88%90%201000%EF%BC%9A10%20%E5%88%A4%E5%AE%9A%E5%8A%A0%208B%22%5D%0A%20%20LO%20--%3E%20SUM%5B%22%E4%B8%A4%E7%AC%94%E6%8A%B5%E6%88%90%207B%22%5D%0A%20%20HI%20--%3E%20SUM%0A%20%20SUM%20--%3E%20SH%5B%22%E9%9A%8F%E5%90%8E%E7%85%A7%E5%B8%B8%E7%AE%97%E6%9C%AF%E7%A7%BB%E4%BD%8D%E5%AF%B9%E9%BD%90%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：Booth 不是万能提速。乘数是 <code>0101…</code> 交替位时，每一步都有加减动作，部分积一条不少，最坏情况反而可能更费——它省的是长 1 游程，不是所有输入。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画华莱士点图，不引入 SRT 除法，不把 DSP48 的 25×18 硬核当 Booth 的定义。浮点尾数乘是无符号阵列加后规格化，符号单独 XOR——那是后课 FMA，不在这里混进补码 Booth。</p><p>后课默认：有符号整数乘可用 Booth 把连续 1 收成加减；部分积仍要被多操作数加法吃掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组成主干已封口；本课打开算术单元：补码乘的部分积编码。</li><li>Booth：游程变成一次加与一次减；基-4 进一步减条数。</li><li>不是先取绝对值；与补码加法器同一套。</li><li>出处：Booth, <em>QJMA</em>, 1951；Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',6))])}const C=n(h,[["render",A]]);export{f as __pageData,C as default};
